CREATE TABLE Benchmark_Testing (
    Benchmark_Testing_ID INTEGER PRIMARY KEY,
    Benchmark_Testing_Name VARCHAR(255)
);

CREATE TABLE Unit (
    Benchmark_Testing_ID INTEGER NOT NULL,
    Unit_ID INTEGER PRIMARY KEY,
    Unit_Name VARCHAR(255),
    FOREIGN KEY (Benchmark_Testing_ID) REFERENCES Benchmark_Testing(Benchmark_Testing_ID)
);
